   pages:[
       \"[
         \\\"\\\",
         {\\\"text\\\":\\\"We became too emboldened, too confident. When we saw the glistening pieces of gold, iron and dark iron sticking out from the red lumps of fleshy earth, we were emboldened by our numbers and equipment.\\\"}
       ]\",
       \"[
         {\\\"text\\\":\\\"I found it easy to convince ourselves of victory, even when we began raiding the Pigkin's bastions. This was our greatest mistake. The forces of Hel declared war, and with it, they brought their strongest warriors and a lack of mercy.\\\"}
       ]\",
       \"[
         {\\\"text\\\":\\\"My people fought on the front lines, and held out in strongholds of brick and mortar. But eventually, the Pigkin stormed the portal and breached our halls.\\\"}
       ]\",
       \"[
         {\\\"text\\\":\\\"They came in overwhelming numbers, picking my brothers and sisters off one by one. The bravest of us managed to destroy the portal before more could come through, but we had left a lot of our own kin on the other side.\\\"}
       ]\",
       \"[
         {\\\"text\\\":\\\"The rest of the Piglins were left in our kingdom, torching our hovels and dismantling our forges.\\\"}
       ]\",
       \"[
         {\\\"text\\\":\\\"It took us months to find stability, and scour out the last bit of Hel's forces. But eventually, we reclaimed what had been left.\\\"}
       ]\",
       \"[
         {\\\"text\\\":\\\"The war between Hel and Stone wasn't the death of our kingdom... But the resulting infighting was.\\\"}
       ]\"
     ],
     title:Journal,
     author:Unknown,
     display:{Lore:[\"Found in the Ancient Mines\"]}
     }"},
     {
       "function": "minecraft:set_name",
